def binary_search(a, key):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] == key:
            return mid
        elif a[mid] < key:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def binary_search_rec(a, lo, hi, key):
    if lo > hi:
        return -1
    mid = lo + (hi - lo) // 2
    if a[mid] == key:
        return mid
    if a[mid] < key:
        return binary_search_rec(a, mid + 1, hi, key)
    return binary_search_rec(a, lo, mid - 1, key)


def lower_bound(a, key):
    """Index of the FIRST element >= key (works with duplicates)."""
    lo, hi = 0, len(a)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if a[mid] < key:
            lo = mid + 1
        else:
            hi = mid            # do not stop: keep looking left
    return lo


def count_iterations(a, key):
    lo, hi, steps = 0, len(a) - 1, 0
    while lo <= hi:
        steps += 1
        mid = lo + (hi - lo) // 2
        if a[mid] == key:
            return steps
        elif a[mid] < key:
            lo = mid + 1
        else:
            hi = mid - 1
    return steps


