import math

def isqrt_floor(x):
    lo, hi = 0, x + 1               # first m with m*m > x
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if mid * mid > x:           # feasible (Yes)
            hi = mid
        else:
            lo = mid + 1
    return lo - 1


def min_speed(piles, h):
    def feasible(k):
        return sum(math.ceil(p / k) for p in piles) <= h

    lo, hi = 1, max(piles)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo


